import{_ as a,o as e,c as t,a3 as s}from"./chunks/framework.CVt6dz2a.js";const k=JSON.parse('{"title":"EP.14 一张图照亮整个场景","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.14-ibl-lighting.md","filePath":"comics/EP.14-ibl-lighting.md","lastUpdated":1793881879000}'),n={name:"comics/EP.14-ibl-lighting.md"};function o(r,i,l,h,d,p){return e(),t("div",null,[...i[0]||(i[0]=[s(`<h1 id="ep-14-一张图照亮整个场景" tabindex="-1">EP.14 一张图照亮整个场景 <a class="header-anchor" href="#ep-14-一张图照亮整个场景" aria-label="Permalink to &quot;EP.14 一张图照亮整个场景&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/14-lighting-ibl/basics">14.1 基础入门：IBL 与 HDR 环境贴图</a> 延伸阅读：<a href="./../guide/14-lighting-ibl/advanced">进阶篇</a> · <a href="./../guide/14-lighting-ibl/practice">实战篇</a> 动手演示：<a href="./../public/demos/lighting/ibl-compare.html">ibl-compare IBL 环境对比</a> · <a href="./../public/demos/lighting/shadow-tuning.html">shadow-tuning 阴影参数调优</a> · <a href="./../public/demos/lighting/product-hdr.html">product-hdr 高保真产品渲染</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱给展示场景摆了 8 盏点光源，金属球却还是一颗灰球——灯越多越亮，但就是不&quot;金属&quot;。</td></tr><tr><td>② 揭秘</td><td>码叔点破：真实世界的光来自整个环境，不是几个点；IBL 用一张 360° 全景图当光源，图上每个像素都是一盏灯，PMREM 预过滤后交给 <code>scene.environment</code>。</td></tr><tr><td>③ 实证</td><td>一行 <code>RGBELoader</code> 加载威尼斯日落 HDR，金属球面立刻映出窗外的天空与落日——模型没变、灯没变，质感像换了渲染器。</td></tr><tr><td>④ 结案</td><td>坑点清单：environment 必须过 PMREM、过曝先查 toneMapping、HDR 别贪大。码叔总结：灯不够别加灯，换环境——一张图照亮全场。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-金属的质感-环境的倒影" tabindex="-1">① 金属的质感 = 环境的倒影 <a class="header-anchor" href="#_1-金属的质感-环境的倒影" aria-label="Permalink to &quot;① 金属的质感 = 环境的倒影&quot;">​</a></h3><p>非金属有&quot;漫反射底色&quot;，随便一盏灯就能照亮；金属几乎没有漫反射，颜色全靠<strong>镜面反射周围环境</strong>。没有环境图时，金属球朝任何方向反射到的都是虚空，自然灰给你看——这就是为什么堆 8 盏点光也没用：点光只给高光斑，给不了连续的倒影。</p><h3 id="_2-ibl-全景图即光源-pmrem-预过滤" tabindex="-1">② IBL：全景图即光源 + PMREM 预过滤 <a class="header-anchor" href="#_2-ibl-全景图即光源-pmrem-预过滤" aria-label="Permalink to &quot;② IBL：全景图即光源 + PMREM 预过滤&quot;">​</a></h3><p>IBL（Image-Based Lighting）把一张等距柱状全景图（2:1）当作&quot;所有方向的光&quot;。但材质有个矛盾：粗糙表面要模糊版环境、镜面金属要清晰版。<strong>PMREMGenerator</strong> 一次性把全景图预过滤成一串不同模糊度的 mip 级别，运行时按 roughness 取用——所以规范写法永远是 <code>scene.environment = pmrem.fromEquirectangular(hdrTex).texture</code>，而不是直接赋值原图。</p><h3 id="_3-四行接入-hdr-但别忘了-洗印" tabindex="-1">③ 四行接入 HDR，但别忘了&quot;洗印&quot; <a class="header-anchor" href="#_3-四行接入-hdr-但别忘了-洗印" aria-label="Permalink to &quot;③ 四行接入 HDR，但别忘了&quot;洗印&quot;&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RGBELoader</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HDR_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">tex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  tex.mapping </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.EquirectangularReflectionMapping</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  scene.environment </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pmrem.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fromEquirectangular</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tex).texture</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  scene.background </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tex          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 可选：背景用原始清晰图</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>HDR 带来的是物理亮度，必须配 <code>renderer.toneMapping = THREE.ACESFilmicToneMapping</code> 压回屏幕范围，否则满屏过曝。光照与背景是两条独立管线：产品页常让 HDR 只管光照、背景压暗或纯色。</p><h3 id="_4-环境选型的手感" tabindex="-1">④ 环境选型的手感 <a class="header-anchor" href="#_4-环境选型的手感" aria-label="Permalink to &quot;④ 环境选型的手感&quot;">​</a></h3><p>RoomEnvironment（程序化摄影棚）零下载量、效果及格，适合开发期与兜底；真实 HDR（Poly Haven 免费可商用）才有&quot;窗外日落&quot;的故事感，适合作品页。分辨率作光照 1k 就够，当清晰背景才上 2k——文件体积与质感要算着花。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：environment 直接赋 HDR 原图会怎样？</strong> 没过 PMREM 预过滤，粗糙反射会闪、可能有立方体接缝。口诀：光照过 PMREM，背景用原图。</li><li><strong>Q：加载 HDR 后场景白成一片？</strong> 没开 tone mapping 或曝光太高：<code>ACESFilmicToneMapping</code> + <code>toneMappingExposure</code> 0.6~1.2；背景太亮降 <code>backgroundIntensity</code>。</li><li><strong>Q：HDR 一张好几 MB，心疼流量？</strong> 作光照用 1k 足够（预过滤后看不出区别）；PMREM 生成后 <code>hdrTex.dispose()</code> 弃原图；或干脆 RoomEnvironment 零下载。</li><li><strong>Q：赋了 environment 没变化？</strong> 查材质是不是 Standard/Physical（Basic/Lambert 不吃环境贴图），再查控制台有没有加载 404。</li><li><strong>Q：背景想要 HDR 的清晰倒影感但又怕抢戏？</strong> <code>scene.backgroundIntensity</code> 压暗，或 <code>backgroundBlurriness</code> 打糊，光照不受影响。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>为什么金属球在没有环境贴图的场景里&quot;堆灯也灰&quot;，而非金属球不会？</li><li><code>scene.environment</code> 与 <code>scene.background</code> 分别管什么？为什么产品页要把它们分设？</li><li>为什么 <code>scene.environment</code> 要先过 PMREMGenerator，而不是直接赋 RGBELoader 加载出的纹理？</li></ol><details><summary>答案</summary><ol><li>金属几乎没有漫反射，颜色主要来自<strong>镜面反射环境</strong>——没有环境图就没有可反射的内容，点光源只能给孤立的高光斑。非金属有漫反射底色，任意方向的光都能照亮它，所以不依赖环境图。</li><li><code>environment</code> 是光照数据源（材质从中取反射与环境光，不显示在画面里）；<code>background</code> 是观众看到的背景。分设后可以&quot;HDR 供光照 + 压暗/纯色背景&quot;，既保住反射质感，又不让背景抢走商品注意力。</li><li>材质按 roughness 需要不同模糊度的环境（粗糙要糊、镜面要清晰），PMREM 把这些预过滤成 mip 链，运行时一次采样即可；直接赋原图等于让着色器现场做大量采样，既慢又会闪烁、可能出现接缝。</li></ol></details>`,19)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
